public class Main {
    public static void main(String[] args) {
        int total = 0;
        outer:
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (i == j) continue outer;
                total += i + j;
            }
        }
        System.out.print(total);
    }
}

public class Main {
    public static void main(String[] args) {
        int x = 0;
        int total = 0;
        do {
            total += ++x;
            if (x == 2) continue;
            total += 10;
        } while (x < 3);
        System.out.print(x + ":" + total);
    }
}

